import React, { useState, useEffect } from 'react';
import { uploadFile, getFiles, downloadEncryptedFile, downloadDecryptedFile, deleteFile } from '../services/api';
import CryptoFlow from '../components/CryptoFlow';
import SciFiAlert from '../components/SciFiAlert';
import { Upload, Server, HardDrive, Terminal, Activity, Play, X, RefreshCw, FileCheck, FileText } from 'lucide-react';
import { Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend } from 'chart.js';
import CryptoTreeFlow from '../components/CryptoTreeFlow';


ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const Dashboard = () => {
  const [files, setFiles] = useState([]);
  const [fileToUpload, setFileToUpload] = useState(null);
  const [uploadStep, setUploadStep] = useState(0);
  const [logs, setLogs] = useState([]);
  const [selectedFile, setSelectedFile] = useState(null);
  const [successMode, setSuccessMode] = useState(false);
  const [customAlert, setCustomAlert] = useState(null);
  const [cryptoMode, setCryptoMode] = useState('hybrid');
  const [activeTab, setActiveTab] = useState("overview");

  useEffect(() => { fetchFiles(); }, []);

  const addLog = (msg) => {
    const timestamp = new Date().toLocaleTimeString('en-US', { hour12: false });
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const fetchFiles = async () => {
    try { const res = await getFiles(); setFiles(res.data); } catch {}
  };

  const resetUpload = () => {
    setFileToUpload(null);
    setSuccessMode(false);
    setUploadStep(0);
  };

  const onFileDrop = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFileToUpload(file);
      setSuccessMode(false);
      addLog(`STAGE: ${file.name} loaded.`);
    }
  };

  const startEncryption = async () => {
    if (!fileToUpload) return;
    setUploadStep(1);
    setLogs([]);
    addLog(`INIT: Protocol for ${fileToUpload.name}`);

    setTimeout(() => { setUploadStep(2); addLog("KEM: Establishing shared secret..."); }, 1000);
    setTimeout(() => { setUploadStep(3); addLog("HKDF: Deriving AES key..."); }, 2500);

    try {
      const res = await uploadFile(fileToUpload, cryptoMode);
      setTimeout(() => { setUploadStep(4); addLog("AES: Encrypting payload..."); }, 3500);
      setTimeout(() => {
        setUploadStep(5);
        setSuccessMode(true);
        addLog(`SUCCESS: Sealed ID: ${res.data.file_id}`);
        fetchFiles();
      }, 5000);
    } catch {
      setUploadStep(0);
      setCustomAlert({ type: 'error', title: 'Upload Failed', message: 'Server error. Check backend logs.' });
    }
  };

  const handleEncryptedDownload = async (file) => {
    try {
      await downloadEncryptedFile(file.id, file.filename);
    } catch {
      setCustomAlert({ type: 'error', title: 'Error', message: 'Download failed.' });
    }
  };

  const handleDecryptedDownload = async (file) => {
    if (file.mode !== 'hybrid') {
      setCustomAlert({ type: 'error', title: 'Action Denied', message: 'RSA is benchmark only.' });
      return;
    }
    try {
      await downloadDecryptedFile(file.id, file.filename);
    } catch {
      setCustomAlert({ type: 'error', title: 'Integrity Breach', message: 'Signature mismatch.' });
    }
  };

  return (
    <div className="p-8 space-y-6 relative h-full flex flex-col">
      {customAlert && <SciFiAlert {...customAlert} onClose={() => setCustomAlert(null)} />}

      {/* ================= MODAL ================= */}
      {selectedFile && (
        <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 backdrop-blur-md">
          <div className="bg-scifi-panel border border-neon-blue w-[720px] p-8 rounded-2xl relative">
            <button onClick={() => setSelectedFile(null)} className="absolute top-4 right-4 text-gray-500 hover:text-white"><X /></button>

            <h2 className="text-2xl font-bold text-white mb-4 flex items-center gap-3">
              <Activity className="text-neon-blue" /> File Security Report
            </h2>

            {/* Tabs */}
            <div className="flex gap-2 mb-4 text-xs">
              <Tab id="overview" active={activeTab} set={setActiveTab} />
              <Tab id="deep" active={activeTab} set={setActiveTab} />
              <Tab id="tree" active={activeTab} set={setActiveTab} />
            </div>

            {/* OVERVIEW */}
            {activeTab === "overview" && (
              <div className="bg-black/50 p-4 rounded-xl border border-gray-800 h-56">
                <Bar
                  data={{
                    labels: ['KEM', 'AES', 'Total'],
                    datasets: [{
                      label: 'Latency (ms)',
                      data: (() => {
                        const m = selectedFile.metrics || {};
                        const p2 = m.phase_2 || {};
                        const p4 = m.phase_4 || {};
                    
                        return [
                          (p2.encap_us || 0) / 1000,
                          p4.aes_enc_ms || 0,
                          m.total_ms || m.total || 0
                        ];
                      })(),
                      backgroundColor: ['#00ff9d', '#00f3ff', '#ffffff'],
                    }]
                  }}
                  options={{ responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } } }}
                />

              </div>
            )}

            
            {/* DEEP */}
            {activeTab === "deep" && (
                
              <div className="grid grid-cols-2 gap-3 text-xs font-mono">
                <Metric label="File Size" value={selectedFile.metrics?.phase_1?.size_bytes + " B"} />
                <Metric label="Read" value={selectedFile.metrics?.phase_1?.read_ms?.toFixed(2) + " ms"} />
                <Metric label="Encapsulation" value={(selectedFile.metrics?.phase_2?.encap_us || 0) + " us"} />
                <Metric label="HKDF" value={(selectedFile.metrics?.phase_3?.hkdf_us || 0) + " us"} />
                <Metric label="AES" value={selectedFile.metrics?.phase_4?.aes_enc_ms?.toFixed(2) + " ms"} />
                <Metric label="Throughput" value={selectedFile.metrics?.phase_4?.throughput_mb_s?.toFixed(2) + " MB/s"} />
                <Metric label="Pack" value={(selectedFile.metrics?.phase_5?.pack_us || 0) + " us"} />
                <Metric label="Total" value={selectedFile.metrics?.total_ms?.toFixed(2) + " ms"} />
              </div>
            )}

            {/* TREE */}
            {activeTab === "tree" && (
              <div className="text-xs font-mono space-y-2">
                <p className="text-neon-blue">✔ Phase 1 — Local Prep</p>
                <p className="ml-4">Size: {selectedFile.metrics?.phase_1?.size_bytes} B</p>

                <p className="text-neon-blue">✔ Phase 2 — X25519</p>
                <p className="ml-4">Encap: {selectedFile.metrics?.phase_2?.encap_us} us</p>

                <p className="text-neon-blue">✔ Phase 3 — HKDF</p>
                <p className="ml-4">Derive: {selectedFile.metrics?.phase_3?.hkdf_us} us</p>

                <p className="text-neon-blue">✔ Phase 4 — AES</p>
                <p className="ml-4">Encrypt: {selectedFile.metrics?.phase_4?.aes_enc_ms} ms</p>

                <p className="text-neon-blue">✔ Phase 5 — Pack</p>
                <p className="ml-4">Pack: {selectedFile.metrics?.phase_5?.pack_us} us</p>
              </div>
            )}

            {/* Buttons */}
            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={async () => {
                  await deleteFile(selectedFile.id);
                  setFiles(prev => prev.filter(f => f.id !== selectedFile.id));
                  setSelectedFile(null);
                }}
                className="px-4 py-2 border border-red-500 text-red-500 rounded hover:bg-red-500/10"
              >
                Delete
              </button>

              <button onClick={() => handleEncryptedDownload(selectedFile)} className="px-4 py-2 border border-gray-500 text-gray-300 rounded hover:bg-white/10">
                Download Encrypted
              </button>

              <button onClick={() => handleDecryptedDownload(selectedFile)} className="px-4 py-2 bg-neon-blue text-black font-bold rounded">
                Decrypt & Download
              </button>
            </div>

          </div>
        </div>
      )}

      {/* ================= HEADER ================= */}
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-white">QS-VAULT</h2>
          <p className="text-gray-400 text-xs font-mono">Post-Quantum Gateway</p>
        </div>
      </div>

      {/* ================= MAIN ================= */}
      <div className="grid grid-cols-3 gap-6 flex-1 min-h-0">

        {/* LEFT */}
        <div className="col-span-2 flex flex-col gap-6">

          {/* Upload */}
          <div className="bg-scifi-panel border border-scifi-border rounded-xl p-6 relative overflow-hidden min-h-[300px] flex flex-col justify-center">
            {uploadStep > 0 || successMode ? (
              <div className="text-center w-full">
                <h3 className="text-neon-green font-bold mb-8 animate-pulse">{successMode ? "ENCRYPTION COMPLETE" : "ENCRYPTION RUNNING..."}</h3>
                <CryptoTreeFlow currentStep={uploadStep === 0 ? 5 : uploadStep} mode={cryptoMode} />
                {successMode && (
                  <div className="mt-8">
                    <button 
                    onClick={resetUpload}
                    className="mt-4 px-6 py-2 bg-white text-black font-bold rounded hover:bg-neon-green transition flex items-center gap-2 mx-auto text-sm"
                    >                   
                    <RefreshCw size={14}/> Encrypt Another
                    </button>

                  </div>
                )}
              </div>
            ) : !fileToUpload ? (
              <label className="border-2 border-dashed border-gray-700 rounded-lg h-full flex flex-col items-center justify-center cursor-pointer">
                <input type="file" onChange={onFileDrop} className="hidden" />
                <Upload className="text-gray-500 mb-4" size={40} />
                <p className="text-white font-bold text-lg">Drop files to Stage</p>
              </label>
            ) : (
              <div className="text-center">
                <FileText className="mx-auto text-neon-green mb-4" size={48} />
                <p className="text-xl font-bold text-white mb-2">{fileToUpload.name}</p>
                <div className="flex justify-center gap-4 mt-8">
                  <button onClick={resetUpload} className="px-6 py-2 border border-gray-600 text-gray-400 rounded">Cancel</button>
                  <button onClick={startEncryption} className="px-6 py-2 bg-neon-green text-black font-bold rounded flex items-center gap-2"><Play size={16} /> Engage</button>
                </div>
              </div>
            )}
          </div>

          {/* Logs */}
          <div className="bg-black border border-gray-800 rounded-xl p-4 flex-1 overflow-y-auto">
            {logs.map((log, i) => <p key={i} className="text-neon-green/80 mb-1 font-mono text-xs">{log}</p>)}
          </div>

        </div>

        {/* RIGHT */}
        <div className="col-span-1 bg-scifi-panel border border-scifi-border rounded-xl p-4 flex flex-col">
          <h3 className="text-white font-bold text-sm mb-4 flex items-center gap-2"><Server size={16} className="text-neon-blue" /> Vault Contents</h3>
          <div className="overflow-y-auto flex-1 space-y-2">
            {files.map(file => (
              <div key={file.id} onClick={() => setSelectedFile(file)} className="p-3 rounded bg-white/5 hover:border-neon-blue cursor-pointer">
                <p className="text-xs text-white font-bold truncate">{file.filename}</p>
                <p className="text-[10px] text-gray-500 mt-1">{new Date(file.date).toLocaleDateString()}</p>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

const Tab = ({ id, active, set }) => (
  <button onClick={() => set(id)} className={`px-3 py-1 rounded capitalize ${active === id ? "bg-neon-blue text-black" : "bg-white/10 text-gray-400"}`}>
    {id}
  </button>
);

const Metric = ({ label, value }) => (
  <div className="bg-black/40 border border-gray-800 p-3 rounded flex justify-between">
    <span className="text-gray-400">{label}</span>
    <span className="text-neon-green">{value}</span>
  </div>
);

export default Dashboard;
